(function() {
    'use strict';

    class PeopleStackAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'PeopleStack: HR Technology Transformation';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    title_en: 'Round 1: Platform Selection',
                    title_es: 'Ronda 1: Seleccion de Plataforma',
                    briefing_en: '<b>Meridian Industrials</b> is a 5,000-employee manufacturing and professional services company with a fragmented HR technology stack across seven point solutions, two custom-built legacy systems, and a decade-old ERP module. HR operating cost per employee is 65% above industry benchmark. The CEO has mandated a full HR technology transformation with a <b>€4.2M budget over 18 months</b>.<br><br>You must evaluate and select one of three competing HCM platforms. Each represents a distinct strategic architecture with genuine trade-offs. Consider functional coverage, total cost of ownership, implementation risk, AI capability, and user adoption potential.<br><br><b>Platform A — Nova HCM:</b> Integrated enterprise suite. Single data model, advanced AI (84% attrition accuracy), €1.84M Year-1 cost, €4.1M 3-year TCO. Needs 3 years of clean data; risk of 20-30% cost overrun.<br><b>Platform B — ClearPath:</b> Mid-market cloud-native. Fast implementation (6-9 months), best UX (4.6/5.0), €1.12M Year-1 cost but €3.8M 3-year TCO due to API cost escalation. Limited workforce planning.<br><b>Platform C — Stratosphere People:</b> Best-of-breed composable stack. Best ATS and analytics (91% attrition accuracy), €1.56M Year-1 cost but €4.6M 3-year TCO. High integration complexity with 11 API integrations.',
                    briefing_es: '<b>Meridian Industrials</b> es una empresa de 5.000 empleados de manufactura y servicios profesionales con una pila tecnologica de RRHH fragmentada en siete soluciones puntuales, dos sistemas legados y un modulo ERP de una decada. El costo operativo de RRHH por empleado es 65% superior al benchmark. La CEO ha ordenado una transformacion tecnologica completa con un <b>presupuesto de €4.2M en 18 meses</b>.<br><br>Debe evaluar y seleccionar una de tres plataformas HCM. Cada una representa una arquitectura estrategica distinta con compromisos genuinos.<br><br><b>Plataforma A — Nova HCM:</b> Suite empresarial integrada. IA avanzada (84% prediccion de desgaste), €1.84M costo Ano 1, €4.1M TCO 3 anos. Requiere datos limpios de 3 anos.<br><b>Plataforma B — ClearPath:</b> Nube nativa mid-market. Implementacion rapida (6-9 meses), mejor UX (4.6/5.0), €1.12M Ano 1 pero €3.8M TCO 3 anos por costos API crecientes.<br><b>Plataforma C — Stratosphere People:</b> Mejor-en-su-clase composable. Mejor ATS y analitica (91%), €1.56M Ano 1 pero €4.6M TCO 3 anos. Alta complejidad de integracion.'
                },
                {
                    title_en: 'Round 2: AI Deployment Strategy',
                    title_es: 'Ronda 2: Estrategia de Despliegue de IA',
                    briefing_en: 'Your platform is being implemented. Now you must make the critical AI deployment decisions for three HR sub-functions most transformed by artificial intelligence.<br><br>For each sub-function, choose a posture: <b>Full Automation</b> (AI replaces human judgment), <b>Augmentation</b> (AI informs human judgment), or <b>Manual</b> (preserve human-led process). Each carries distinct trade-offs across efficiency, employee experience, and algorithmic bias risk.<br><br>You must also set data governance parameters. The EU AI Act classifies AI in hiring as "high-risk." GDPR Article 22 restricts automated decision-making affecting employees. Germany operations require Works Council approval for behavioral monitoring.<br><br>Consider carefully: broader data collection improves AI accuracy but increases compliance risk and the People Risk Index.',
                    briefing_es: 'Su plataforma esta siendo implementada. Ahora debe tomar las decisiones criticas de despliegue de IA para tres subfunciones de RRHH transformadas por inteligencia artificial.<br><br>Para cada subfuncion, elija una postura: <b>Automatizacion Total</b> (IA reemplaza juicio humano), <b>Aumentacion</b> (IA informa juicio humano), o <b>Manual</b> (preservar proceso humano). Cada una tiene compromisos distintos entre eficiencia, experiencia del empleado y riesgo de sesgo algoritmico.<br><br>Tambien debe establecer parametros de gobernanza de datos. La Ley de IA de la UE clasifica la IA en contratacion como "alto riesgo." El Articulo 22 del RGPD restringe la toma de decisiones automatizada.'
                },
                {
                    title_en: 'Round 3: Change Management',
                    title_es: 'Ronda 3: Gestion del Cambio',
                    briefing_en: 'The platform is live and AI modules are deploying. But HR Business Partners (HRBPs), whose advisory roles are being substantially redefined, are exhibiting measurable resistance. Employee satisfaction with HR services is declining during the transition.<br><br>You have a <b>€280,000 change management budget</b> to allocate across eight interventions mapped to Kotter\'s 8-Step Change Model. You cannot fund all eight — you must prioritize.<br><br>The effectiveness of each intervention depends on your earlier platform and AI choices. Consider which Kotter steps are most critical given your current HRBP resistance level and the adoption challenges specific to your chosen platform.',
                    briefing_es: 'La plataforma esta activa y los modulos de IA se estan desplegando. Pero los HR Business Partners (HRBPs), cuyos roles de asesoria estan siendo redefinidos, exhiben resistencia medible. La satisfaccion de empleados con servicios de RRHH esta disminuyendo durante la transicion.<br><br>Tiene un <b>presupuesto de gestion del cambio de €280.000</b> para distribuir entre ocho intervenciones mapeadas al Modelo de 8 Pasos de Kotter. No puede financiar todas — debe priorizar.'
                }
            ];

            this.PLATFORM_DATA = {
                A: { name: 'Nova HCM', cost: 1840000, tco3y: 4100000, hrCostBase: -22, hrCostNoData: -18, timeHireBase: 16, timeHireNoData: 12, attritionBase: 84, attritionNoData: 45, complianceBase: 88, adoptionMod: 1.0, uxRating: 4.3 },
                B: { name: 'ClearPath', cost: 1120000, tco3y: 3800000, hrCostBase: -16, timeHireBase: 18, attritionBase: 72, complianceBase: 78, adoptionMod: 1.15, uxRating: 4.6 },
                C: { name: 'Stratosphere People', cost: 1560000, tco3y: 4600000, hrCostBase: -14, hrCostFail: -8, timeHireBase: 20, timeHireFail: 10, attritionBase: 91, attritionFail: 55, complianceBase: 72, adoptionMod: 0.85, uxRating: 3.6 }
            };

            this.INTERVENTIONS = [
                { id: 'int1Check', cost: 45000, resistReduction: 12, exsBoost: 4, adoptionBoost: 0, kotterPhase: 'early' },
                { id: 'int2Check', cost: 28000, resistReduction: 8, exsBoost: 0, adoptionBoost: 0, kotterPhase: 'early' },
                { id: 'int3Check', cost: 22000, resistReduction: 6, exsBoost: 0, adoptionBoost: 0, kotterPhase: 'early' },
                { id: 'int4Check', cost: 35000, resistReduction: 4, exsBoost: 3, adoptionBoost: 18, kotterPhase: 'early' },
                { id: 'int5Check', cost: 40000, resistReduction: 3, exsBoost: 0, adoptionBoost: 12, kotterPhase: 'late' },
                { id: 'int6Check', cost: 18000, resistReduction: 0, exsBoost: 6, adoptionBoost: 0, kotterPhase: 'late' },
                { id: 'int7Check', cost: 55000, resistReduction: 2, exsBoost: 0, adoptionBoost: 22, kotterPhase: 'late' },
                { id: 'int8Check', cost: 37000, resistReduction: 20, exsBoost: 8, adoptionBoost: 0, kotterPhase: 'late' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 4200000,
                    hrCostReduction: 0,
                    timeHireImprovement: 0,
                    attritionAccuracy: 0,
                    complianceScore: 100,
                    exScore: 61,
                    peopleRiskIndex: 0,
                    hrbpResistance: 45,
                    platform: '',
                    dataQualityDone: false,
                    worksCouncilNotified: false,
                    andreaBonused: false,
                    talentAI: '',
                    perfAI: '',
                    analyticsAI: '',
                    adverseImpact: false,
                    candidateDisclosure: false,
                    managerNotif: false,
                    dataRetention: 12,
                    interventionsFunded: [],
                    changeBudgetUsed: 0,
                    eventsTriggered: [],
                    hrCostHistory: [],
                    timeHireHistory: [],
                    attritionHistory: [],
                    complianceHistory: [],
                    exsHistory: [],
                    priHistory: [],
                    resistanceHistory: [],
                    scoreHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    round: 1,
                    platform: 'A',
                    dataQuality: false,
                    worksCouncil: false,
                    andrea: false
                };
            }
            this._updateBriefing(state);
            this._setupBudgetTracker();
        }

        _setupBudgetTracker() {
            var checks = document.querySelectorAll('.intervention-check');
            checks.forEach(function(chk) {
                chk.addEventListener('change', function() {
                    var total = 0;
                    checks.forEach(function(c) {
                        if (c.checked) {
                            total += parseInt(c.getAttribute('data-cost') || '0');
                        }
                    });
                    var remaining = 280000 - total;
                    var display = document.getElementById('changeBudgetDisplay');
                    if (display) {
                        display.textContent = '€' + remaining.toLocaleString();
                        display.style.color = remaining < 0 ? '#e74c3c' : '#27ae60';
                    }
                });
            });
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var lang = 'en';
            try {
                lang = window.mySimulation && window.mySimulation.currentLanguage ? window.mySimulation.currentLanguage : 'en';
            } catch(e) {}

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = lang === 'es' ? round.briefing_es : round.briefing_en;

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = lang === 'es' ? round.title_es : round.title_en;

            var r1 = document.getElementById('round1Panel');
            var r2 = document.getElementById('round2Panel');
            var r3 = document.getElementById('round3Panel');
            var period = state.currentPeriod || 1;

            if (r1) r1.style.display = period === 1 ? 'block' : 'none';
            if (r2) r2.style.display = period === 2 ? 'block' : 'none';
            if (r3) r3.style.display = period === 3 ? 'block' : 'none';
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var platformSel = document.getElementById('platformSelect');
                if (platformSel) decisions.platform = platformSel.value;
                var dq = document.getElementById('dataQualityCheck');
                if (dq) decisions.dataQuality = dq.checked;
                var wc = document.getElementById('worksCouncilCheck');
                if (wc) decisions.worksCouncil = wc.checked;
                var an = document.getElementById('andreaCheck');
                if (an) decisions.andrea = an.checked;
                decisions.round = 1;
            } else if (period === 2) {
                var ta = document.getElementById('talentAISelect');
                if (ta) decisions.talentAI = ta.value;
                var pa = document.getElementById('perfAISelect');
                if (pa) decisions.perfAI = pa.value;
                var aa = document.getElementById('analyticsAISelect');
                if (aa) decisions.analyticsAI = aa.value;
                var ai = document.getElementById('adverseImpactCheck');
                if (ai) decisions.adverseImpact = ai.checked;
                var cd = document.getElementById('candidateDisclosureCheck');
                if (cd) decisions.candidateDisclosure = cd.checked;
                var mn = document.getElementById('managerNotifCheck');
                if (mn) decisions.managerNotif = mn.checked;
                var rt = document.getElementById('retentionSelect');
                if (rt) decisions.dataRetention = parseInt(rt.value);
                decisions.round = 2;
            } else if (period === 3) {
                var totalCost = 0;
                var funded = [];
                var self = this;
                this.INTERVENTIONS.forEach(function(intv) {
                    var el = document.getElementById(intv.id);
                    if (el && el.checked) {
                        funded.push(intv.id);
                        totalCost += intv.cost;
                    }
                });
                if (totalCost > 280000) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('budget_exceeded'), 'warning'
                    );
                    return false;
                }
                decisions.interventionsFunded = funded;
                decisions.changeBudgetUsed = totalCost;
                decisions.round = 3;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var events = [];
            var period = state.currentPeriod;

            if (d.round === 1) {
                var pdata = this.PLATFORM_DATA[d.platform];
                ds.platform = d.platform;
                ds.dataQualityDone = d.dataQuality;
                ds.worksCouncilNotified = d.worksCouncil;
                ds.andreaBonused = d.andrea;

                var platformCost = pdata.cost;
                if (d.dataQuality) platformCost += 180000;
                if (d.andrea) platformCost += 15000;
                ds.budget -= platformCost;

                if (d.platform === 'A') {
                    if (d.dataQuality) {
                        ds.hrCostReduction = pdata.hrCostBase;
                        ds.timeHireImprovement = pdata.timeHireBase;
                        ds.attritionAccuracy = pdata.attritionBase;
                    } else {
                        ds.hrCostReduction = pdata.hrCostNoData;
                        ds.timeHireImprovement = pdata.timeHireNoData;
                        ds.attritionAccuracy = pdata.attritionNoData;
                    }
                    ds.complianceScore = pdata.complianceBase;
                } else if (d.platform === 'B') {
                    ds.hrCostReduction = pdata.hrCostBase;
                    ds.timeHireImprovement = pdata.timeHireBase;
                    ds.attritionAccuracy = pdata.attritionBase;
                    ds.complianceScore = pdata.complianceBase;
                } else if (d.platform === 'C') {
                    var integrationFail = !d.dataQuality && Math.random() < 0.4;
                    if (integrationFail) {
                        ds.hrCostReduction = pdata.hrCostFail;
                        ds.timeHireImprovement = pdata.timeHireFail;
                        ds.attritionAccuracy = pdata.attritionFail;
                        ds.hrbpResistance += 15;
                        events.push('integration_failure');
                    } else {
                        ds.hrCostReduction = pdata.hrCostBase;
                        ds.timeHireImprovement = pdata.timeHireBase;
                        ds.attritionAccuracy = pdata.attritionBase;
                    }
                    ds.complianceScore = pdata.complianceBase;
                }

                if (d.andrea) {
                    ds.hrbpResistance -= 8;
                }

                ds.exScore = 61;

            } else if (d.round === 2) {
                ds.talentAI = d.talentAI;
                ds.perfAI = d.perfAI;
                ds.analyticsAI = d.analyticsAI;
                ds.adverseImpact = d.adverseImpact;
                ds.candidateDisclosure = d.candidateDisclosure;
                ds.managerNotif = d.managerNotif;
                ds.dataRetention = d.dataRetention;

                var aiCost = 0;
                if (d.adverseImpact) aiCost += 45000;
                ds.budget -= aiCost;

                if (d.talentAI === 'full') {
                    ds.hrCostReduction -= 6;
                    ds.timeHireImprovement += 4;
                    ds.hrbpResistance += 10;
                    if (!d.adverseImpact) {
                        events.push('algorithm_audit');
                        ds.complianceScore -= 18;
                        ds.exScore -= 8;
                        ds.peopleRiskIndex += 15;
                        ds.budget -= 35000;
                    }
                    if (!d.candidateDisclosure) {
                        ds.complianceScore -= 5;
                        ds.peopleRiskIndex += 5;
                    }
                } else if (d.talentAI === 'augment') {
                    ds.hrCostReduction -= 3;
                    ds.timeHireImprovement += 2;
                    ds.hrbpResistance += 4;
                } else {
                    ds.hrbpResistance -= 2;
                }

                if (d.perfAI === 'full') {
                    ds.hrCostReduction -= 5;
                    ds.hrbpResistance += 15;
                    ds.exScore -= 6;
                    if (!d.managerNotif) {
                        ds.complianceScore -= 8;
                        ds.peopleRiskIndex += 10;
                    }
                    ds.complianceScore -= 5;
                    ds.peopleRiskIndex += 8;
                } else if (d.perfAI === 'augment') {
                    ds.hrCostReduction -= 2;
                    ds.hrbpResistance += 6;
                    ds.exScore -= 2;
                } else {
                    ds.hrbpResistance -= 3;
                    ds.exScore += 2;
                }

                if (d.analyticsAI === 'full') {
                    ds.attritionAccuracy = Math.min(ds.attritionAccuracy + 5, 95);
                    ds.hrbpResistance += 8;
                    ds.exScore -= 5;
                    ds.peopleRiskIndex += 12;
                    if (d.dataRetention > 24) {
                        ds.complianceScore -= 6;
                        ds.peopleRiskIndex += 5;
                    }
                } else if (d.analyticsAI === 'moderate') {
                    ds.attritionAccuracy = Math.max(ds.attritionAccuracy, 74);
                    ds.hrbpResistance += 3;
                    ds.exScore -= 2;
                } else {
                    ds.attritionAccuracy = Math.max(ds.attritionAccuracy - 10, 50);
                    ds.exScore += 1;
                }

                if (!ds.worksCouncilNotified && (d.analyticsAI === 'full' || d.perfAI === 'full')) {
                    events.push('works_council_injunction');
                    ds.complianceScore -= 15;
                    ds.hrbpResistance += 15;
                    ds.peopleRiskIndex += 10;
                    ds.budget -= 28000;
                }

                if (ds.hrbpResistance > 65) {
                    if (Math.random() < 0.4) {
                        events.push('star_hrbp_resignation');
                        ds.timeHireImprovement -= 8;
                        ds.exScore -= 10;
                        ds.hrbpResistance += 12;
                    }
                }

                if (ds.attritionAccuracy < 50 && Math.random() < 0.35) {
                    events.push('engineer_attrition_surge');
                    ds.timeHireImprovement -= 14;
                    ds.exScore -= 10;
                }

                var allAugment = d.talentAI === 'augment' && d.perfAI === 'augment' && d.analyticsAI === 'moderate';
                if (allAugment && events.length === 0 && Math.random() < 0.2) {
                    events.push('positive_ai_press');
                    ds.exScore += 6;
                    ds.timeHireImprovement += 2;
                    ds.complianceScore += 8;
                }

            } else if (d.round === 3) {
                ds.interventionsFunded = d.interventionsFunded;
                ds.changeBudgetUsed = d.changeBudgetUsed;
                ds.budget -= d.changeBudgetUsed;

                var platformMod = this.PLATFORM_DATA[ds.platform] ? this.PLATFORM_DATA[ds.platform].adoptionMod : 1.0;
                var earlyCount = 0;
                var lateCount = 0;
                var self = this;

                d.interventionsFunded.forEach(function(id) {
                    var intv = self.INTERVENTIONS.find(function(i) { return i.id === id; });
                    if (intv) {
                        ds.hrbpResistance -= Math.round(intv.resistReduction * platformMod);
                        ds.exScore += Math.round(intv.exsBoost * platformMod);
                        if (intv.kotterPhase === 'early') earlyCount++;
                        else lateCount++;
                    }
                });

                var sequenceBonus = 1.0;
                if (earlyCount >= 2 && lateCount >= 2) {
                    sequenceBonus = 1.25;
                } else if (earlyCount === 0 && lateCount > 0) {
                    sequenceBonus = 0.7;
                } else if (earlyCount > 0 && lateCount === 0) {
                    sequenceBonus = 0.8;
                }

                var totalAdoptionBoost = 0;
                d.interventionsFunded.forEach(function(id) {
                    var intv = self.INTERVENTIONS.find(function(i) { return i.id === id; });
                    if (intv) {
                        totalAdoptionBoost += intv.adoptionBoost;
                    }
                });

                var adoptionFactor = (totalAdoptionBoost / 100) * sequenceBonus * platformMod;
                ds.hrCostReduction -= Math.round(adoptionFactor * 4);
                ds.timeHireImprovement += Math.round(adoptionFactor * 3);
                ds.attritionAccuracy = Math.min(ds.attritionAccuracy + Math.round(adoptionFactor * 5), 98);

                if (d.interventionsFunded.indexOf('int8Check') !== -1) {
                    if (Math.random() < 0.5) {
                        events.push('hrbp_reskilling_success');
                        ds.hrbpResistance -= 15;
                        ds.exScore += 10;
                    }
                }

                if (ds.hrbpResistance > 0) {
                    var resistPenalty = Math.round(ds.hrbpResistance / 10);
                    ds.peopleRiskIndex += resistPenalty;
                }

                var exsDecline = Math.max(0, 61 - ds.exScore);
                ds.peopleRiskIndex += Math.round(exsDecline / 5) * 8;
            }

            ds.hrbpResistance = Math.max(0, Math.min(100, ds.hrbpResistance));
            ds.complianceScore = Math.max(0, Math.min(100, ds.complianceScore));
            ds.exScore = Math.max(0, Math.min(100, ds.exScore));
            ds.peopleRiskIndex = Math.max(0, Math.min(100, ds.peopleRiskIndex));
            ds.hrCostReduction = Math.max(-50, Math.min(0, ds.hrCostReduction));

            ds.eventsTriggered = ds.eventsTriggered.concat(events);

            ds.hrCostHistory.push(ds.hrCostReduction);
            ds.timeHireHistory.push(ds.timeHireImprovement);
            ds.attritionHistory.push(ds.attritionAccuracy);
            ds.complianceHistory.push(ds.complianceScore);
            ds.exsHistory.push(ds.exScore);
            ds.priHistory.push(ds.peopleRiskIndex);
            ds.resistanceHistory.push(ds.hrbpResistance);

            var compositeScore = Math.round(
                (Math.abs(ds.hrCostReduction) / 38 * 30) +
                (ds.timeHireImprovement / 22 * 25) +
                (ds.attritionAccuracy / 91 * 20) +
                (ds.complianceScore / 100 * 25)
            );
            compositeScore = Math.max(0, Math.min(100, compositeScore));
            ds.scoreHistory.push(compositeScore);

            this._showEvents(events);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                round: d.round,
                platform: ds.platform,
                hrCostReduction: ds.hrCostReduction,
                timeHireImprovement: ds.timeHireImprovement,
                attritionAccuracy: ds.attritionAccuracy,
                complianceScore: ds.complianceScore,
                exScore: ds.exScore,
                peopleRiskIndex: ds.peopleRiskIndex,
                hrbpResistance: ds.hrbpResistance,
                budget: ds.budget,
                compositeScore: compositeScore,
                events: events
            };
        }

