        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var composite = r.compositeScore || 0;
            var pri = r.peopleRiskIndex || 0;

            var performance = 'Needs Improvement';
            if (composite >= 70 && pri <= 25) performance = 'Excellent CHRO — Balanced Transformation';
            else if (composite >= 70 && pri > 25) performance = 'Efficient but Unsustainable';
            else if (composite >= 50 && pri <= 30) performance = 'Solid Foundation';
            else if (composite >= 50) performance = 'Good Progress with Risks';

            var insights = [];
            if (r.complianceScore < 70) insights.push('Compliance gaps need urgent attention. Review GDPR requirements and Works Council obligations.');
            if (r.hrbpResistance > 50) insights.push('HRBP resistance remains high. Change management sequencing may need adjustment.');
            if (r.exScore < 55) insights.push('Employee experience declined significantly. Consider balancing automation with human-centered approaches.');
            if (pri > 40) insights.push('People Risk Index is elevated. The transformation may face sustainability challenges.');
            if (composite >= 75 && pri <= 20) insights.push('Outstanding balance of efficiency and people outcomes. This represents best-practice HR transformation.');
            if (insights.length === 0) insights.push('Solid overall performance. Review the KPI breakdown for optimization opportunities.');

            return {
                compositeScore: composite,
                peopleRiskIndex: pri,
                performance: performance,
                insights: insights
            };
        }

